226. impl<const N: usize, const A: usize, S: BssStorage> FixedSizeBumpAllocator<N, A, S> {
227.     ///
228.     /// # Description
229.     ///
230.     /// Creates a new fixed-size bump allocator.
231.     ///
232.     /// # Returns
233.     ///
234.     /// Returns a new allocator.
235.     ///
236.     /// # Safety
237.     ///
238.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
239.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
240.     /// backend causes independent bump counters, which leads to overlapping slot reservations
241.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
242.     ///
243.     pub const unsafe fn new() -> Self {
244.         Self {
245.             next_slot: AtomicUsize::new(0),
246.             _storage: PhantomData,
247.         }
248.     }
249. 
250.     ///
251.     /// # Description
252.     ///
253.     /// Allocates the next fixed-size slot as a raw byte array.
254.     ///
255.     /// # Returns
256.     ///
257.     /// On success, returns a mutable reference to a unit-sized byte array.
258.     ///
259.     /// # Errors
260.     ///
261.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
262.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
263.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
264.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
265.     ///
266.     // SAFETY-SPEC: `external_body` because the success path materializes a
267.     // `&'static mut [u8; N]` from a backend-provided address (`usize as *mut`), a
268.     // raw-memory operation Verus cannot verify without a `PointsTo` permission for
269.     // the externally-owned `BssStorage` region. Mirrors the `src/libs/raw-array`
270.     // pattern. Registered in `verus-ai-logs/tcb-allowed.md`.
271.     #[verus_spec(result =>
272.         requires bump_view(self).inv(),
273.         ensures
274.             match result {
275.                 Ok(slot) => {
276.                     let v = bump_view(self);
277.                     let a = slot_ref_addr(slot);
278.                     &&& a % (v.unit_align as int) == 0
279.                     &&& v.base <= a
280.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
281.                 },
282.                 Err(e) => e == BumpAllocError::Exhausted,
283.             },
284.     )]
285.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
286.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
287.         let idx: usize = loop {
288.             let current: usize = self.next_slot.load(Ordering::Acquire);
289.             if current >= S::NUM_UNITS {
290.                 return Err(BumpAllocError::Exhausted);
291.             }
292.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
293.             if self
294.                 .next_slot
295.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
296.                 .is_ok()
297.             {
298.                 break current;
299.             }
300.         };
301. 
302.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
303.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
304. 
305.         let base: usize = S::as_mut_ptr() as usize;
306.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
307.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
308.         let storage_end: usize = base
309.             .checked_add(S::STORAGE_SIZE)
310.             .ok_or(BumpAllocError::Overflow)?;
311.         if end > storage_end {
312.             return Err(BumpAllocError::OutOfBounds);
313.         }
314.         if !ptr.is_multiple_of(A) {
315.             return Err(BumpAllocError::Misaligned);
316.         }
317. 
318.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
319.         // out at most once by atomic compare-and-swap.
320.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
321.     }
