342.     ///
343.     // SAFETY-SPEC: `external_body` for the same reason as `alloc` (it delegates to
344.     // `alloc` and then re-materializes the slot reference as `&'static mut
345.     // MaybeUninit<T>`). The size/alignment guard arms make the `T`-vs-`(N, A)`
346.     // contract caller-visible. Registered in `verus-ai-logs/tcb-allowed.md`.
347.     #[verus_spec(result =>
348.         requires bump_view(self).inv(),
349.         ensures
350.             match result {
351.                 Ok(slot) => {
352.                     let v = bump_view(self);
353.                     let a = slot_ref_addr(slot);
354.                     &&& vstd::layout::size_of::<T>() == N as nat
355.                     &&& vstd::layout::align_of::<T>() <= A as nat
356.                     &&& a % (v.unit_align as int) == 0
357.                     &&& v.base <= a
358.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
359.                 },
360.                 Err(e) => {
361.                     &&& e == BumpAllocError::SizeMismatch
362.                         || e == BumpAllocError::AlignmentMismatch
363.                         || e == BumpAllocError::Exhausted
364.                     &&& (e == BumpAllocError::SizeMismatch ==> vstd::layout::size_of::<T>()
365.                         != N as nat)
366.                     &&& (e == BumpAllocError::AlignmentMismatch ==> vstd::layout::align_of::<T>()
367.                         > A as nat)
368.                 },
369.             },
370.     )]
371.     pub unsafe fn alloc_as<T>(&self) -> Result<&'static mut MaybeUninit<T>, BumpAllocError> {
372.         if core::mem::size_of::<T>() != N {
373.             return Err(BumpAllocError::SizeMismatch);
374.         }
375.         if core::mem::align_of::<T>() > A {
376.             return Err(BumpAllocError::AlignmentMismatch);
377.         }
378. 
379.         let slot: &'static mut [u8; N] = self.alloc()?;
380.         // SAFETY: size/alignment checks above guarantee this cast is valid.
381.         Ok(unsafe { &mut *(slot.as_mut_ptr() as *mut MaybeUninit<T>) })
382.     }
383. }
